const SOURCE_PREFIX = 'en';
const isSource = (iso) => String(iso || '').toLowerCase().indexOf(SOURCE_PREFIX) === 0;
const projectRef = (p) => {
  const id = p && p.id ? String(p.id) : '';
  const br = p && p.branch ? String(p.branch) : '';
  return (br && br !== 'master') ? id + ':' + br : id;
};
const readName = (n) => (typeof n === 'string') ? n : ((n && (n.web || n.other || n.ios || n.android)) || '');
const out = [];
for (const item of $input.all()) {
  const b = (item.json && item.json.body) ? item.json.body : (item.json || {});
  const ev = String(b.event || '');
  const project = projectRef(b.project);
  if (!project) continue;
  const push = (keyId, name, tags, reason) => {
    if (!keyId) return;
    out.push({ json: {
      projectId: project,
      projectName: (b.project && b.project.name) || '',
      branch: (b.project && b.project.branch) || '',
      event: ev,
      action: b.action || '',
      keyId: String(keyId),
      keyNameHint: name || '',
      reason: reason,
      actor: (b.user && b.user.email) || ''
    } });
  };
  if (ev === 'project.key.added') {
    push(b.key && b.key.id, readName(b.key && b.key.name), b.key && b.key.tags, 'new key');
  } else if (ev === 'project.keys.added') {
    for (const k of (b.keys || [])) push(k.id, readName(k.name), k.tags, 'new key');
  } else if (ev === 'project.translation.updated') {
    const iso = b.language && b.language.iso;
    const t = b.translation || {};
    if (isSource(iso) && t.value !== t.previous_value) push(b.key && b.key.id, readName(b.key && b.key.name), null, 'source edited (' + iso + ')');
  } else if (ev === 'project.translations.updated') {
    for (const t of (b.translations || [])) {
      const iso = t.language && t.language.iso;
      if (isSource(iso) && t.value !== t.previous_value) push(t.key && t.key.id, readName(t.key && t.key.name), null, 'source edited (' + iso + ')');
    }
  }
}
const seen = {};
const deduped = [];
for (const o of out) {
  const sig = o.json.projectId + '|' + o.json.keyId;
  if (seen[sig]) continue;
  seen[sig] = true;
  deduped.push(o);
}
return deduped;

const TAG = 'to_review';
const SOURCE_PREFIX = 'en';
const meta = $('Normalize Lokalise Events').all();
const rows = $input.all();
const readName = (n) => (typeof n === 'string') ? n : ((n && (n.web || n.other || n.ios || n.android)) || '');
const isEmptyValue = (v) => {
  if (v === null || v === undefined || v === '') return true;
  if (typeof v === 'object') return Object.keys(v).every((k) => !v[k]);
  return false;
};
const out = [];
for (let i = 0; i < rows.length; i++) {
  const m = (meta[i] && meta[i].json) || {};
  const j = rows[i].json || {};
  if (j.error) continue;
  const k = j.key || j;
  if (!k || !k.key_id) continue;
  const tags = Array.isArray(k.tags) ? k.tags : [];
  const targets = [];
  for (const t of (k.translations || [])) {
    const iso = String(t.language_iso || '').toLowerCase();
    if (iso.indexOf(SOURCE_PREFIX) === 0) continue;
    if (isEmptyValue(t.translation)) continue;
    if (t.is_unverified === true) continue;
    targets.push({ translationId: t.translation_id, languageIso: t.language_iso, translation: t.translation });
  }
  out.push({ json: {
    projectId: m.projectId,
    projectName: m.projectName || '',
    keyId: String(k.key_id),
    keyName: readName(k.key_name) || m.keyNameHint || '',
    event: m.event || '',
    reason: m.reason || '',
    actor: m.actor || '',
    tag: TAG,
    currentTags: tags,
    alreadyTagged: tags.indexOf(TAG) !== -1,
    targets: targets,
    targetCount: targets.length
  } });
}
return out;

const kept = $('Skip Keys Already Tagged').all();
const out = [];
for (const it of kept) {
  const j = it.json || {};
  for (const t of (j.targets || [])) {
    if (!t.translationId) continue;
    out.push({ json: {
      projectId: j.projectId,
      keyId: j.keyId,
      keyName: j.keyName,
      translationId: t.translationId,
      languageIso: t.languageIso,
      translation: t.translation
    } });
  }
}
return out;

